document.addEventListener("DOMContentLoaded", () => {
  const filter = document.getElementById("severity-filter");
  const exportLink = document.getElementById("csv-export");
  const status = document.getElementById("triage-status");
  const tbody = document.getElementById("incident-rows");
  const fields = ["incident_id", "service", "severity", "status", "created_at"];

  async function updateTriage() {
    const severity = filter.value;
    const query = new URLSearchParams({severity});
    exportLink.href = `/api/incidents/export?${query}`;
    status.textContent = "Loading incidents…";
    tbody.replaceChildren();
    try {
      const response = await fetch(`/api/incidents?${query}`);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const incidents = await response.json();
      // Ignore a previous request if the filter changed while it was loading.
      if (severity !== filter.value) return;
      for (const incident of incidents) {
        const tr = document.createElement("tr");
        for (const field of fields) {
          const td = document.createElement("td");
          td.textContent = incident[field];
          tr.appendChild(td);
        }
        tbody.appendChild(tr);
      }
      status.textContent = `${incidents.length} ${severity} incident${incidents.length === 1 ? "" : "s"}`;
    } catch (error) {
      if (severity === filter.value) status.textContent = `Could not load incidents: ${error.message}`;
    }
  }

  filter.addEventListener("change", updateTriage);
  updateTriage();
});
